def interleave_multiple_lists(lists):
    out = []
    i = 0
    while True:
        added = False
        for lst in lists:
            if i < len(lst):
                out.append(lst[i])
                added = True
        if not added:
            break
        i += 1
    return out

def bucket_sort_by_string_length(strings, ranges):
    buckets = [[] for _ in ranges]
    for s in strings:
        for i, (lo, hi) in enumerate(ranges):
            if lo <= len(s) <= hi:
                buckets[i].append(s)
                break
    return [sorted(b) for b in buckets]

def is_identity_matrix(m):
    n = len(m)
    for row in m:
        if len(row) != n:
            return False
    for i in range(n):
        for j in range(n):
            expected = 1 if i == j else 0
            if m[i][j] != expected:
                return False
    return True

