def is_valid_temperature_reading(s):
    if len(s) < 2:
        return False
    unit = s[-1]
    if unit not in ('C', 'F'):
        return False
    num_part = s[:-1]
    if not num_part:
        return False
    idx = 1 if num_part[0] in '+-' else 0
    rest = num_part[idx:]
    if not rest or rest.startswith('.') or rest.endswith('.'):
        return False
    if rest.count('.') > 1:
        return False
    if not rest.replace('.', '').isdigit():
        return False
    return True

