def reverse_in_base(n, base):
    if n == 0:
        return 0
    digits = []
    x = n
    while x > 0:
        digits.append(x % base)
        x //= base
    value = 0
    for d in digits:
        value = value * base + d
    return value

def center_text_block(lines, width):
    result = []
    for s in lines:
        if len(s) >= width:
            result.append(s)
        else:
            total = width - len(s)
            left = total // 2
            right = total - left
            result.append(' ' * left + s + ' ' * right)
    return result

def double_shift_day_delta(hh, mm, offset_minutes):
    total = hh * 60 + mm + offset_minutes
    day_delta = total // 1440
    if day_delta < 0:
        return "previous"
    elif day_delta > 0:
        return "next"
    return "same"

def sort_by_frequency_then_last_occurrence(items):
    from collections import Counter
    c = Counter(items)
    last_idx = {}
    for i, x in enumerate(items):
        last_idx[x] = i
    uniq = list(dict.fromkeys(items))
    return sorted(uniq, key=lambda x: (-c[x], last_idx[x]))

def weighted_frequency(pairs):
    d = {}
    for item, w in pairs:
        d[item] = d.get(item, 0) + w
    return d

def invert_unique_tags(d):
