def longest_decreasing_run_length(lst):
    if not lst:
        return 0
    best = 1
    cur = 1
    for i in range(1, len(lst)):
        if lst[i] < lst[i - 1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def capitalize_after_colon(s):
    lowered = s.lower()
    chars = list(lowered)

    def cap_at(idx):
        for i in range(idx, len(chars)):
            if chars[i].isalpha():
                chars[i] = chars[i].upper()
                return

    cap_at(0)
    idx = lowered.find(": ")
    while idx != -1:
        cap_at(idx + 2)
        idx = lowered.find(": ", idx + 1)
    return "".join(chars)

def rank_normalize_scores_avg_tie(scores):
    n = len(scores)
    if n <= 1:
        return [0.0 for _ in scores]
    s = sorted(scores)
    positions = {}
    for i, v in enumerate(s):
        positions.setdefault(v, []).append(i)
    avg_rank = {v: sum(p) / len(p) for v, p in positions.items()}
    return [round(avg_rank[v] / (n - 1), 4) for v in scores]

def is_valid_flight_number(s):
