def is_valid_e164_phone_number(s):
    if not s.startswith('+'):
        return False
    digits = s[1:]
    if not digits.isdigit():
        return False
    if not (8 <= len(digits) <= 15):
        return False
    return digits[0] != '0'

def rotate_string_right(s, n):
    if not s:
        return ""
    n = n % len(s)
    return s[-n:] + s[:-n] if n != 0 else s

def is_valid_time_range(s):
    import re
    m = re.fullmatch(r'(\d{2}):(\d{2})-(\d{2}):(\d{2})', s)
    if not m:
        return False
    h1, m1, h2, m2 = (int(x) for x in m.groups())
    if not (0 <= h1 <= 23 and 0 <= m1 <= 59 and 0 <= h2 <= 23 and 0 <= m2 <= 59):
        return False
    return h1 * 60 + m1 < h2 * 60 + m2

def group_by_remainder(lst, n):
    result = {}
    for x in lst:
        r = x % n
        result.setdefault(r, []).append(x)
    return result

def shift_right_and_fill(lst, n, fill):
    length = len(lst)
    if n <= 0:
        return lst[:]
    if n >= length:
        return [fill] * length
    return [fill] * n + lst[:length - n]

def partition_by_threshold(lst, t):
    below = [x for x in lst if x < t]
    at_or_above = [x for x in lst if x >= t]
    return (below, at_or_above)
